from store import list_notifications

def sync_notifications(rows, checkpoint, deliver):
    for row in list_notifications(rows):
        if row['sequence'] <= checkpoint:
            continue
        deliver(row)  # May raise. Caller persists the last yielded checkpoint.
        checkpoint = row['sequence']
        yield checkpoint

